|description2 = Catching the boomerang while it is returning back refunds 40% of the ability's {{sti|'''total''' cooldown}}.
|description3 = ''Enemies can be hit only once per pass.''
|cooldown     = {{ap|16 to 10}}
|range        = {{dv|{{tip|cr|icononly = true}} {{tt|1125|Outgoing missile}}|{{tip|cr|icononly = true}} {{tt|3000|Return missile, from the return location}}}}
|speed        = {{dv|{{tt|2500 - 1400|Outgoing missile speed, acceleration -3000}}|{{tt|60 - 2600|Return missile speed, acceleration 800}}}}
|cast time    = {{fd|0.25}}
|width        = {{dv|{{tip|er|icononly = true}} {{tt|110|Outgoing missile width}}|{{tt|150|Return missile width}}}}
|targeting    = Direction
|affects      = Enemies
